ublished_products_public_read","schemaname":"software_discovery","with_check":null}]}}$payload$::jsonb; op jsonb; expected jsonb; actual jsonb;
BEGIN
 PERFORM set_config('lock_timeout','10s',true);
 PERFORM set_config('TimeZone','UTC',true);
 PERFORM pg_advisory_xact_lock(7232003);
 LOCK TABLE software_discovery.products,software_discovery.product_attributes,software_discovery.product_anchors,software_discovery.product_problems,software_discovery.product_audiences,software_discovery.product_attribute_evidence,software_discovery.product_anchor_evidence,software_discovery.product_problem_evidence,software_discovery.product_audience_evidence,software_discovery.claim_evidence,software_discovery.evidence_sources,software_discovery.attributes,software_discovery.anchors,software_discovery.problems,software_discovery.audiences,software_discovery.escape_routes,software_discovery.escape_route_products IN SHARE ROW EXCLUSIVE MODE;
 IF coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.products WHERE status='published'),'[]'::jsonb)<>data->'snapshot'->'published_products' OR coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved),'[]'::jsonb)<>data->'snapshot'->'approved_published_routes' THEN RAISE EXCEPTION 'PR5.104 publication state drift or repeated apply; fresh preflight required'; END IF;
 IF NOT has_function_privilege('anon','software_discovery.product_discovery_page(text)','EXECUTE') OR has_table_privilege('anon','software_discovery.claim_evidence','SELECT') THEN RAISE EXCEPTION 'PR5.104 private evidence boundary drift'; END IF;
 IF (SELECT coalesce(jsonb_agg(jsonb_build_object('table_name',c.relname,'rls_enabled',c.relrowsecurity) ORDER BY c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='software_discovery' AND c.relname IN ('products','escape_routes','escape_route_products'))<>data->'snapshot'->'public_read_rls' OR (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname),'[]'::jsonb) FROM pg_policies p WHERE schemaname='software_discovery' AND tablename IN ('products','escape_routes','escape_route_products'))<>data->'snapshot'->'public_read_policies' THEN RAISE EXCEPTION 'PR5.104 public read policy drift'; END IF;
 FOR op IN SELECT value FROM jsonb_array_elements(data->'guards') LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(jsonb_populate_record(NULL::software_discovery.%I,r))-''created_at''-''updated_at'' j FROM jsonb_array_elements($1) r) x',op->>'table') INTO expected USING op->'rows';
  EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(t)-''created_at''-''updated_at'' j FROM software_discovery.%I t WHERE %s) x',op->>'table',op->>'where') INTO actual;
  IF expected<>actual THEN RAISE EXCEPTION 'PR5.104 stored baseline drift: %',op->>'table'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM software_discovery.products WHERE id IN ('0ff28f7c-7c3c-4869-bb62-bdc804f344de','0a0ba2cb-36c6-4130-b823-05ef6bd13f26','22562b1f-e16a-455c-8c0f-d4f3f432d2f9') AND software_discovery.product_discovery_page(slug) IS NOT NULL) THEN RAISE EXCEPTION 'PR5.104 draft public visibility drift'; END IF;
 UPDATE software_discovery.products SET status='published' WHERE id IN ('0ff28f7c-7c3c-4869-bb62-bdc804f344de','0a0ba2cb-36c6-4130-b823-05ef6bd13f26','22562b1f-e16a-455c-8c0f-d4f3f432d2f9');
 UPDATE software_discovery.escape_routes SET status='published',editorially_approved=true WHERE id='e8c13edd-bcec-47ac-80a6-414cc9260267';
 IF (SELECT count(*) FROM software_discovery.products WHERE status='published')<>24 OR (SELECT count(*) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved)<>10 THEN RAISE EXCEPTION 'PR5.104 post-publication count mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM software_discovery.products p WHERE p.id IN ('0ff28f7c-7c3c-4869-bb62-bdc804f344de','0a0ba2cb-36c6-4130-b823-05ef6bd13f26','22562b1f-e16a-455c-8c0f-d4f3f432d2f9') AND (software_discovery.product_discovery_page(p.slug) IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(software_discovery.product_discovery_page(p.slug)->'anchors') a WHERE a->>'slug'='grammarly' AND a->>'scope'='personal-english-passive-construction-review' AND a->>'verificationStatus'='verified' AND length(a->>'description')>0 AND jsonb_array_length(a->'sources')>0) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(software_discovery.product_discovery_page(p.slug)->'attributes') a WHERE a->>'slug'='privacy-friendly' AND a->'value'='true'::jsonb AND a->>'verificationStatus'='verified' AND jsonb_array_length(a->'sources')>0))) THEN RAISE EXCEPTION 'PR5.104 public qualified projection missing'; END IF;

 IF EXISTS(SELECT 1 FROM software_discovery.products p WHERE p.id IN ('0ff28f7c-7c3c-4869-bb62-bdc804f344de','0a0ba2cb-36c6-4130-b823-05ef6bd13f26','22562b1f-e16a-455c-8c0f-d4f3f432d2f9') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(software_discovery.product_discovery_page(p.slug)->'attributes') a JOIN software_discovery.attributes t ON t.slug='reviewed-local-operation' JOIN software_discovery.product_attributes c ON c.product_id=p.id AND c.attribute_id=t.id WHERE a->>'slug'=t.slug AND a->>'value'=c.value_text AND a->>'verificationStatus'='verified' AND jsonb_array_length(a->'sources')>0)) THEN RAISE EXCEPTION 'PR5.104 public operation statement missing'; END IF;
 RAISE SQLSTATE 'ZSR01' USING MESSAGE='Privacy publication rehearsal only';
EXCEPTION WHEN SQLSTATE 'ZSR01' THEN RAISE NOTICE 'Privacy publication rehearsal rolled back; no changes persisted';
END $privacy_publish$;
